  const normalized=new Map(),nationalNames=new Map();
  const norm=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  for(const [name,entry] of Object.entries(catalog.clubs)){
    const base=name.replace(/\s*\([^)]*\)\s*$/,'');
    for(const key of new Set([norm(name),norm(base)])){
      const scoped=(entry.country||'')+'|'+key;
      if(!normalized.has(scoped))normalized.set(scoped,entry);
      else if(normalized.get(scoped)?.src!==entry.src)normalized.set(scoped,null);
      if(!normalized.has(key))normalized.set(key,entry);
      else if(normalized.get(key)?.src!==entry.src)normalized.set(key,null);
    }
  }
  for(const [code,entry] of Object.entries(catalog.nations)){
    for(const name of [entry.name,code])nationalNames.set(norm(name),entry);
  }
  function club(value,country){
    const name=typeof value==='object'?value?.name:value;
    country=country||value?.country_code||value?.country;
    return catalog.clubs[name]||(country?normalized.get(country+'|'+norm(name)):null)||normalized.get(norm(name))||null;
  }
  function nation(value){
    const code=typeof value==='object'?(value?.nation_code||value?.code||value?.nationality_code||value?.name):value;
    return catalog.nations[code]||nationalNames.get(norm(code))||null;
  }
  function isGenerated(value){
    if(!/^data:image\/svg\+xml[;,]/i.test(String(value||'')))return false;
    try{
      const raw=String(value),svg=/;base64,/i.test(raw)
        ?(typeof Buffer!=='undefined'?Buffer.from(raw.split(',')[1],'base64').toString('utf8'):atob(raw.split(',')[1]))
        :decodeURIComponent(raw.slice(raw.indexOf(',')+1));
      return svg.includes('M60 4 108 20v48')&&svg.includes('<text');
    }catch(_e){return false;}
  }
  function uploaded(value){return /^data:image\/(png|jpeg|webp);base64,/i.test(String(value||''));}
  function source(value){
    if(!value)return null;
    const entry=club(value);
    if(entry)return entry.src;
    const existing=String(value.crest_data||'');
    return uploaded(existing)?existing:null;
  }
  return Object.freeze({version:63,catalog,club,nation,isGenerated,uploaded,source});
